cmd:
d=$(mktemp -d) && mkdir -p "$d/js/vendor" && touch "$d/index.html" "$d/js/vendor/x.js" && printf "const SHELL = [
  'index.html',
];
" > "$d/sw.js" && ! node scripts/check-precache.mjs --root "$d" && printf "const SHELL = [
  'index.html',
  'js/vendor/x.js',
];
" > "$d/sw.js" && node scripts/check-precache.mjs --root "$d"
